const body = $input.first().json;
const alerts = body.alerts || [];
const alert = alerts[0] || {};
const labels = alert.labels || {};
const values = alert.values || {};
const desc = (alert.annotations && (alert.annotations.description || alert.annotations.summary) || '').slice(0, 600);
const errorCount = values.A || values.B || 0;

return [{
  json: {
    alertName: labels.alertname || 'Error Spike',
    instance: labels.instance || 'pocat-backend',
    severity: labels.severity || 'critical',
    errorCount: errorCount,
    description: desc,
    startTime: alert.startsAt || new Date().toISOString(),
    generatorURL: alert.generatorURL || '',
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 300,
      messages: [
        {
          role: 'system',
          content: 'POCAT 카드 거래 플랫폼 에러 스파이크 분석 AI입니다. 한국어로 3줄 이내 답변하세요.'
        },
        {
          role: 'user',
          content: '에러 스파이크 감지\n알림명: ' + (labels.alertname || '') + '\n인스턴스: ' + (labels.instance || '') + '\n에러 건수: ' + errorCount + '건\n내용: ' + desc + '\n\n에러 분류, 근본 원인 추정, 롤백 필요 여부를 각 1줄로 답변하세요.'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const analysis = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '분석 실패';
const prev = $('Parse Error Context').first().json;

return [{
  json: {
    slackPayload: {
      text: '🔴 *[에러 스파이크] ' + prev.alertName + ' — ' + prev.errorCount + '건*',
      attachments: [{
        color: 'danger',
        fields: [
          { title: '인스턴스', value: prev.instance || '-', short: true },
          { title: '에러 건수', value: String(prev.errorCount), short: true },
          { title: '내용', value: prev.description || '-', short: false },
          { title: 'AI 분석', value: analysis, short: false }
        ],
        footer: 'POCAT Monitoring | ' + prev.startTime
      }]
    }
  }
}];
